namespace RonSijm.FluidHumidifier.Factories.Transfer;

public class WebAppFactory(string resourceName = null, Action<Humidifier.Transfer.WebApp> factoryAction = null) : ResourceFactory<Humidifier.Transfer.WebApp>(resourceName)
{

    internal InnerWebAppWebAppCustomizationFactory WebAppCustomizationFactory { get; set; }

    internal InnerWebAppIdentityProviderDetailsFactory IdentityProviderDetailsFactory { get; set; }

    internal InnerWebAppWebAppUnitsFactory WebAppUnitsFactory { get; set; }

    internal InnerWebAppEndpointDetailsFactory EndpointDetailsFactory { get; set; }

    protected override Humidifier.Transfer.WebApp Create()
    {
        var webAppResult = CreateWebApp();
        factoryAction?.Invoke(webAppResult);

        return webAppResult;
    }

    private Humidifier.Transfer.WebApp CreateWebApp()
    {
        var webAppResult = new Humidifier.Transfer.WebApp
        {
            GivenName = InputResourceName,
        };

        return webAppResult;
    }
    public override void CreateChildren(Humidifier.Transfer.WebApp result)
    {
        base.CreateChildren(result);

        result.WebAppCustomization ??= WebAppCustomizationFactory?.Build();
        result.IdentityProviderDetails ??= IdentityProviderDetailsFactory?.Build();
        result.WebAppUnits ??= WebAppUnitsFactory?.Build();
        result.EndpointDetails ??= EndpointDetailsFactory?.Build();
    }

} // End Of Class

